-- =====================================================================
-- ChessOx — Master Schema (Idempotent)
-- =====================================================================
-- Safe to run on a fresh OR existing Supabase project.
-- Uses IF NOT EXISTS / DROP IF EXISTS / CREATE OR REPLACE throughout
-- so re-running never errors on duplicate objects.
--===========================================================

-- =====================================================================
-- SECTION 1: ENUMS
-- =====================================================================
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'app_role') THEN
    EXECUTE 'CREATE TYPE public.app_role AS ENUM (''admin'', ''moderator'', ''user'')';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'premium_tier') THEN
    EXECUTE 'CREATE TYPE public.premium_tier AS ENUM (''free'', ''gold'', ''platinum'', ''maharaja'')';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'game_result') THEN
    EXECUTE 'CREATE TYPE public.game_result AS ENUM (''white'', ''black'', ''draw'', ''ongoing'', ''aborted'')';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'time_class') THEN
    EXECUTE 'CREATE TYPE public.time_class AS ENUM (''bullet'', ''blitz'', ''rapid'', ''classical'', ''correspondence'')';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'friend_status') THEN
    EXECUTE 'CREATE TYPE public.friend_status AS ENUM (''pending'', ''accepted'', ''blocked'')';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'club_role') THEN
    EXECUTE 'CREATE TYPE public.club_role AS ENUM (''owner'', ''admin'', ''member'')';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'subscription_status') THEN
    EXECUTE 'CREATE TYPE public.subscription_status AS ENUM (''active'', ''cancelled'', ''past_due'', ''trialing'', ''inactive'')';
  END IF;
END $$;

-- =====================================================================
-- SECTION 2: UTILITY TRIGGER FUNCTION
-- =====================================================================
CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
REVOKE EXECUTE ON FUNCTION public.set_updated_at() FROM PUBLIC, anon, authenticated;

-- =====================================================================
-- SECTION 3: PROFILES
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.profiles (
  id           UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  username     TEXT UNIQUE NOT NULL,
  full_name    TEXT NOT NULL,
  bio          TEXT DEFAULT '',
  country      TEXT DEFAULT 'India',
  avatar_url    TEXT,
  banner_url    TEXT,
  website       TEXT,
  youtube_url   TEXT,
  instagram_url TEXT,
  facebook_url  TEXT,
  twitter_url   TEXT,
  title        TEXT,
  premium_tier public.premium_tier NOT NULL DEFAULT 'free',
  last_seen    TIMESTAMPTZ DEFAULT now(),
  is_online    BOOLEAN NOT NULL DEFAULT false,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  iq_rating INT NOT NULL DEFAULT 100,
  board_theme  TEXT NOT NULL DEFAULT 'royal',
  piece_theme  TEXT NOT NULL DEFAULT 'classic',
  display_name TEXT,
  community_score INT NOT NULL DEFAULT 0,
  iq_level INT NOT NULL DEFAULT 100
);
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS board_theme TEXT NOT NULL DEFAULT 'royal';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS piece_theme TEXT NOT NULL DEFAULT 'classic';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS display_name TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS community_score INT NOT NULL DEFAULT 0;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS iq_level INT NOT NULL DEFAULT 100;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS state TEXT DEFAULT '';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS district TEXT DEFAULT '';
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS favorite_opening TEXT DEFAULT '';
GRANT SELECT ON public.profiles TO anon;
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Profiles are publicly viewable" ON public.profiles;
CREATE POLICY "Profiles are publicly viewable"
  ON public.profiles FOR SELECT USING (true);
DROP POLICY IF EXISTS "Users update own profile" ON public.profiles;
CREATE POLICY "Users update own profile"
  ON public.profiles FOR UPDATE
  USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS "Users insert own profile" ON public.profiles;
CREATE POLICY "Users insert own profile"
  ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);
DROP TRIGGER IF EXISTS trg_profiles_updated_at ON public.profiles;
CREATE TRIGGER trg_profiles_updated_at
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- Migrate full_name to full_name if necessary
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='profiles' AND column_name='full_name') THEN
  END IF;
END $$;

-- =====================================================================
-- SECTION 4: USER ROLES
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.user_roles (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  role       public.app_role NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (user_id, role)
);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users view own roles" ON public.user_roles;
CREATE POLICY "Users view own roles"
  ON public.user_roles FOR SELECT USING (auth.uid() = user_id);

CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role public.app_role)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role
  )
$$;
REVOKE EXECUTE ON FUNCTION public.has_role(UUID, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(UUID, public.app_role) TO authenticated, service_role;

-- Zero-arg convenience wrapper: "is the CURRENT caller an admin". The clan
-- system's RLS policies and admin_delete_clan() call this, but it was never
-- defined anywhere in the schema — every query against a policy using it
-- failed outright with "function public.is_admin() does not exist" (a hard
-- parse-time error, not just an access-denied), and admin_delete_clan()
-- could never be called. Defined here (immediately after has_role, which it
-- wraps) so it exists before its first use further down this file.
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT public.has_role(auth.uid(), 'admin')
$$;
REVOKE EXECUTE ON FUNCTION public.is_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated, service_role;

